SELECT ws.ws_order_number, ws.ws_quantity, ws.ws_list_price, ws.ws_quantity * ws.ws_list_price AS total_list_price, ws.ws_ext_discount_amt, CASE WHEN ws.ws_ext_discount_amt > 0 THEN ws.ws_net_paid - ws.ws_ext_discount_amt ELSE ws.ws_net_paid END AS net_paid_adj, CASE WHEN d.d_month_seq BETWEEN 1 AND 3 THEN 'Q1' WHEN d.d_month_seq BETWEEN 4 AND 6 THEN 'Q2' WHEN d.d_month_seq BETWEEN 7 AND 9 THEN 'Q3' ELSE 'Q4' END AS quarter_label, d.d_year, d.d_day_name, CASE d.d_holiday WHEN 'Y' THEN 'Holiday' ELSE 'Non-Holiday' END AS holiday_flag, ws.ws_net_profit + ws.ws_ext_ship_cost AS profit_plus_ship, ws.ws_net_paid_inc_tax - ws.ws_ext_tax AS tax_adjusted_paid FROM web_sales ws JOIN date_dim d ON ws.ws_sold_date_sk = d.d_date_sk WHERE d.d_year = 1920 AND d.d_holiday = 'N'
